function watchToggle(e){if(!e||(e.kind!=="plane"&&e.kind!=="ship"))return;if(watchHas(e))WATCH=WATCH.filter(function(w){return!(w.k===e.kind&&String(w.id)===String(e.id))});else{WATCH.push({k:e.kind,id:e.id,n:e.n||String(e.id),s:""});setLayer(e.kind==="plane"?"air":"ship",true);note("Watching",esc(e.n||e.id)+" is on your watchlist. It appears in the Briefing, and you are told when its status changes.")}ls("ojos-watch",WATCH);if(selected===e)entDossier(e);brDraw()}
