function watchState(w,o){if(w.k==="plane"){if(!o)return WL.air&&PLANES.length?"gone":"";return(o.alt||0)>250&&(o.v||0)>40?"air":"ground"}if(!o)return"";return(o.sog||0)>1?"moving":"stopped"}
